goals = {g['id']: g for g in json.loads(CANONICAL.read_text())['goals']}
rows = []
for goal_id, scene in scenes.items():
    out = OWN / 'images' / goal_id
    out.mkdir(parents=True, exist_ok=True)
    subprocess.run(['node', str(ROOT / 'scripts/prepare_goal_visualization.mjs'), goal_id, '--landscape=curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_BIOLOGIE.de.json', '--subject=biologie', '--provider=OpenAI image_gen (Codex built-in)'], check=True, stdout=subprocess.DEVNULL)
    prompt = style + '\n' + scene + '\n'
    (out / 'original-generation.prompt.md').write_text(prompt)
    (out / 'prompt.de.md').write_text(prompt)
    write(out / 'whole-current-goal.readonly.json', goals[goal_id])
    rows.append({'goalId': goal_id, 'wholeGoal': goals[goal_id], 'actualGenerationPrompt': bind(out / 'original-generation.prompt.md'), 'helperPreparationMetadata': bind(ROOT / f'tmp/goal-visualizations/{goal_id}/metadata.json'), 'actualProvider': 'OpenAI image_gen (Codex built-in)', 'modelVersion': None, 'independentVApproval': False})
refs = [ROOT / f'curricula/DE/Gymnasium/visualizations/biologie/{goal_id}/{goal_id}.png' for goal_id in ['5a47f591-f2ac-5457-872a-22c89c2dbe93','f2306104-e846-5c25-bfbf-5f3e33db623a']]
write(OWN / 'nine-current-goals-and-original-prompts.readonly.author-entry.json', {'schemaVersion': 1, 'role': 'Nine inactive original image generation inputs, no source/material/V approval', 'createdAtUtc': datetime.now(timezone.utc).isoformat(), 'canonical': bind(CANONICAL), 'nineGoals': rows, 'actuallyInspectedStyleReferences': [bind(p) for p in refs], 'styleReferenceUse': 'Actual original-size inspection; explicit written style description, no existing image edits', 'activeWrites': 0, 'strictGain': 0, 'humanApproval': False})
print(json.dumps({'nineOriginalPrompts': len(rows), 'activeWrites': 0, 'strictGain': 0}))
